from collections import deque

def enclosed_components(grid):
    h,w=len(grid),len(grid[0]); from collections import Counter
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=bg or (r,c) in seen: continue
        q=deque([(r,c)]); seen.add((r,c)); cells=[]; edge=False
        while q:
          y,x=q.popleft(); cells.append((y,x)); edge |= y==0 or x==0 or y==h-1 or x==w-1
          for ny,nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=ny<h and 0<=nx<w and grid[ny][nx]==bg and (ny,nx) not in seen:
              seen.add((ny,nx));q.append((ny,nx))
        if not edge: comps.append(cells)
